### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

long long solve_one(int n, const vector<pair<int,int>>& edges) {
    // 建立邻接表
    vector<vector<int>> g(n + 1);
    for (auto &e : edges) {
        int u = e.first, v = e.second;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    // BFS 分层计数
    vector<char> vis(n + 1, 0);
    vector<int> parity(n + 1, 0);  // 0 偶层，1 奇层
    long long cnt0 = 0, cnt1 = 0;

    queue<int> q;
    q.push(1);
    vis[1] = 1;
    parity[1] = 0;
    cnt0++;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) {
            if (!vis[v]) {
                vis[v] = 1;
                parity[v] = parity[u] ^ 1;
                if (parity[v] == 0) cnt0++;
                else cnt1++;
                q.push(v);
            }
        }
    }
    return n + min(cnt0, cnt1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        long long K;         // K >= 2，不影响答案
        cin >> n >> K;
        vector<pair<int,int>> edges;
        edges.reserve(n - 1);
        for (int i = 0; i < n - 1; ++i) {
            int u, v;
            cin >> u >> v;
            edges.emplace_back(u, v);
        }
        cout << solve_one(n, edges) << "\n";
    }
    return 0;
}
